const CACHE={COUNT:6,CAPTURE_R:96,CAPTURE_T:4.5,ACTIVATE_R:620,AGGRO:520,LEASH:680,CONTEST:145,MIN_BASE:760,MAX_BASE:Math.min(2850,Math.min(WORLD_W,WORLD_H)*.38),SEP:760};
function cacheSpotBlocked(x,y){if(dist2(x,y,BASE_X,BASE_Y)<CACHE.MIN_BASE*CACHE.MIN_BASE)return true;try{if(typeof pointBlockedByTerrain==='function'&&pointBlockedByTerrain(x,y,48))return true;}catch{}for(const d of state.depots||[])if(dist2(x,y,d.x,d.y)<sq((d.r||34)+100))return true;for(const s of state.structures||[])if(Number.isFinite(s.x)&&dist2(x,y,s.x,s.y)<150*150)return true;return false;}
function generateCaches(){const out=[];let tries=0;while(out.length<CACHE.COUNT&&tries++<1600){const a=Math.random()*Math.PI*2,d=CACHE.MIN_BASE+Math.random()*(CACHE.MAX_BASE-CACHE.MIN_BASE),x=BASE_X+Math.cos(a)*d,y=BASE_Y+Math.sin(a)*d;if(x<120||y<120||x>WORLD_W-120||y>WORLD_H-120||cacheSpotBlocked(x,y)||out.some(c=>dist2(x,y,c.x,c.y)<CACHE.SEP*CACHE.SEP))continue;out.push({id:`cache-${out.length}-${Math.random().toString(36).slice(2,7)}`,x,y,r:30,capture:0,captured:false,guardsSpawned:false});}return out;}
