function makeGuard(type,box,x,y){let cfg;try{cfg=typeof enemyCfg==='function'?enemyCfg(type):null;}catch{}cfg=cfg||CONFIG.RAVAGER;const level=Math.floor((state.elapsed||0)/60)+1,hp=(Number(cfg.BASE_HP)||6)+level*(Number(cfg.HP_PER_LEVEL)||.5);return{type,x,y,hp,maxHp:hp,speed:((Number(cfg.BASE_SPEED)||65)+level*(Number(cfg.SPEED_PER_LEVEL)||.5))*(Number(CONFIG.DIRECTOR.ENEMY_SPEED_MULTIPLIER)||.3),r:Number(cfg.RADIUS)||7,damage:Number(cfg.BASE_DAMAGE)||2,burn:0,burnTick:0,slowFactor:1,slowTime:0,animOffset:Math.random()*100,rangeCooldown:0,specialCooldown:0,v47GuardBoxId:box.id,v47GuardHomeX:x,v47GuardHomeY:y};}
function guardSpawnPoint(box,index,count){for(let n=0;n<14;n++){const a=index/count*Math.PI*2+n*.47+Math.random()*.25,d=155+Math.random()*70,x=box.x+Math.cos(a)*d,y=box.y+Math.sin(a)*d;if(x<20||y<20||x>WORLD_W-20||y>WORLD_H-20)continue;try{if(typeof navPointBlocked==='function'&&navPointBlocked(x,y,12))continue;}catch{}return{x,y};}return{x:box.x+150,y:box.y};}
function spawnCacheGuards(box){if(box.guardsSpawned||box.captured)return;box.guardsSpawned=true;const types=Math.floor((state.elapsed||0)/60)>=4?['ravager','runner','brute']:['ravager','ravager','runner'];for(let i=0;i<types.length;i++){const p=guardSpawnPoint(box,i,types.length);state.enemies.push(makeGuard(types[i],box,p.x,p.y));}enemyGridDirty=true;if(els?.message)els.message.textContent='Resource cache disturbed — local aliens are defending it.';}
function nearestCacheUnit(box,maxDist,forGuard=false){let best=null,bd=maxDist*maxDist;for(const u of state.units||[]){if(!activeUnit(u)||(forGuard&&roleOf(u)==='spotter'))continue;const d=dist2(u.x,u.y,box.x,box.y);if(d<bd){best=u;bd=d;}}return best;}
