function stepGuard(e,tx,ty,speed,dt){const dx=tx-e.x,dy=ty-e.y,d=Math.hypot(dx,dy)||1,step=Math.min(d,speed*dt),base=Math.atan2(dy,dx);for(const off of [0,.48,-.48,.9,-.9,1.35,-1.35]){const a=base+off,nx=e.x+Math.cos(a)*step,ny=e.y+Math.sin(a)*step;if(guardBlocked(nx,ny,e.r))continue;e.x=nx;e.y=ny;return true;}return false;}
function updateGuards(dt,guards){for(const e of guards){if(e.hp<=0)continue;if(e.burn>0){e.burn-=dt;e.burnTick-=dt;if(e.burnTick<=0){try{hitEnemy(e,CONFIG.FLAME.BURN_TICK_DAMAGE*state.mods.flameDamage);}catch{e.hp-=CONFIG.FLAME.BURN_TICK_DAMAGE;}e.burnTick=CONFIG.FLAME.BURN_TICK_INTERVAL;if(e.hp<=0)continue;}}if((e.slowTime||0)>0)e.slowTime=Math.max(0,e.slowTime-dt);else e.slowFactor=1;const box=guardBox(e);if(!box||box.captured){e.hp=0;continue;}const target=nearestCacheUnit(box,CACHE.AGGRO,true),slow=(e.slowTime||0)>0?(e.slowFactor||1):1;let tx=e.v47GuardHomeX,ty=e.v47GuardHomeY;if(target){tx=target.x;ty=target.y;}else if(dist2(e.x,e.y,box.x,box.y)>CACHE.LEASH*CACHE.LEASH){tx=box.x;ty=box.y;}const d2=dist2(tx,ty,e.x,e.y);if(target){const rr=unitRadiusSafe(target),reach=e.r+rr+CONFIG.TOWER_DURABILITY.MELEE_ATTACK_RANGE;if(d2<=reach*reach){target.hp-=e.damage*CONFIG.TOWER_DURABILITY.MELEE_DAMAGE_MULTIPLIER*dt;continue;}}if(d2>100){let speed=e.speed*slow;try{if(typeof pointInRiver==='function'&&pointInRiver(e.x,e.y))speed*=CONFIG.RIVERS.SLOW_FACTOR;}catch{}stepGuard(e,tx,ty,speed,dt);}}}
