function updateCaches(dt){for(const box of state.v47ResourceCaches||[]){if(box.captured)continue;const activator=nearestCacheUnit(box,CACHE.ACTIVATE_R);if(activator&&!box.guardsSpawned)spawnCacheGuards(box);const unit=nearestCacheUnit(box,CACHE.CAPTURE_R),contested=(state.enemies||[]).some(e=>e.v47GuardBoxId===box.id&&e.hp>0&&dist2(e.x,e.y,box.x,box.y)<=CACHE.CONTEST*CACHE.CONTEST);if(unit&&!contested){box.capture=Math.min(CACHE.CAPTURE_T,box.capture+dt);if(box.capture>=CACHE.CAPTURE_T){box.captured=true;const reward=rewardForCache();if(!state.debug?.unlimitedCash)state.credits=(Number(state.credits)||0)+reward.gold;state.metal=(Number(state.metal)||0)+reward.metal;state.enemies=state.enemies.filter(e=>e.v47GuardBoxId!==box.id);enemyGridDirty=true;if(els?.message)els.message.textContent=`Resource cache secured: +${reward.gold} gold, +${reward.metal} metal.`;updateHud();}}else if(!unit)box.capture=Math.max(0,box.capture-dt*.35);}}
