const HORDE={FIRST:26,BASE_GAP:48,MIN_GAP:36,GAP_DROP:1.2,START_SIZE:34,SIZE_PER_MIN:6,BASE_MAX:100,MAX_SIZE:220,BATCH:5,BATCH_INTERVAL:.50,START_RADIUS:1500,MAX_RADIUS:2350,RADIUS_GROW:.85,ARC:.62,RADIAL_JITTER:300};
