function balance(type){if(type==='swarm'||type==='ravager'||type==='runner')return{hp:.58,damage:.55};if(type==='climber'||type==='harvesterhunter')return{hp:.62,damage:.58};if(type==='spitter'||type==='flyer'||type==='burrower'||type==='saboteur')return{hp:.68,damage:.60};if(type==='brute')return{hp:.72,damage:.64};if(type==='acidlobber')return{hp:.76,damage:.66};if(type==='crusher')return{hp:.80,damage:.68};if(type==='siegebeast')return{hp:.86,damage:.72};return{hp:.68,damage:.62};}
