if(typeof fireEnemyShot==='function'){const shotBeforeV47=fireEnemyShot;fireEnemyShot=function(e,t){const n=state.enemyBullets?.length||0,r=shotBeforeV47(e,t);if(e?.v47DamageMult&&state.enemyBullets?.length>n){const b=state.enemyBullets[state.enemyBullets.length-1];if(b&&Number.isFinite(b.dmg))b.dmg*=e.v47DamageMult;}return r;};}
